"""Account collection-style form for the draft storefront; no account changes."""
import base64
import hashlib
from html import escape
from crm_tracking import public_https

SCRIPT = """const form=document.querySelector('form'),files=form.elements.media,status=document.querySelector('[role=status]'),button=form.querySelector('button[type=submit]'),previews=document.querySelector('[data-previews]');let urls=[];
files.addEventListener('change',()=>{urls.forEach(URL.revokeObjectURL);urls=[];previews.replaceChildren();for(const file of files.files){const image=document.createElement(file.type.startsWith('video/')?'video':'img');if(image.tagName==='VIDEO'){image.controls=true;image.preload='metadata'}else image.alt='Selected photo';image.src=URL.createObjectURL(file);urls.push(image.src);previews.append(image);const label=document.createElement('span');label.textContent=file.name;previews.append(label)}});
form.addEventListener('submit',event=>{event.preventDefault();if(button.disabled)return;const selected=[...files.files];if(selected.length>5||selected.filter(f=>f.type.startsWith('video/')).length>1||selected.some(f=>f.size>(f.type.startsWith('video/')?150:25)*1024*1024)||selected.reduce((n,f)=>n+f.size,0)>250*1024*1024){status.textContent='Choose up to five files, including one video. Photos: 25 MB each. Video: 150 MB. Total: 250 MB.';return}button.disabled=true;status.textContent='Uploading your review…';const request=new XMLHttpRequest();request.open('POST',location.href);request.timeout=900000;request.upload.onprogress=e=>{if(e.lengthComputable)status.textContent=e.loaded===e.total?'Upload complete. Saving your review…':'Uploading your review: '+Math.round(e.loaded/e.total*100)+'%'};const failed=()=>{button.disabled=false;status.textContent='Your review was not submitted. Check your connection, fields and file sizes, then try again.'};request.onerror=failed;request.ontimeout=failed;request.onload=()=>{if(request.status!==200){failed();return}form.hidden=true;document.querySelector('h1').textContent='Thank you for your review';status.textContent='Your review has been received by Sports Cave and is awaiting review.';status.focus();document.querySelector('main').append(previews)};const data=new FormData(form);if(!data.get('form_token'))data.delete('form_token');request.send(data)});"""


def form_headers(headers):
    digest=base64.b64encode(hashlib.sha256(SCRIPT.encode()).digest()).decode()
    return {**headers,'Content-Security-Policy':headers['Content-Security-Policy'].replace("style-src 'unsafe-inline';", "style-src 'unsafe-inline'; script-src 'sha256-"+digest+"'; connect-src 'self'; img-src https: blob:;")}


def storefront_html(product,token):
    product=product or {}
    title=escape(product.get('title') or 'Your Sports Cave experience')
    image=product.get('image_url') or ''
    hero='<img class="edition" src="'+escape(image,quote=True)+'" alt="Your edition" width="80" height="80">' if public_https(image) else ''
    rating=''.join('<label><input type="radio" name="rating" value="'+str(n)+'"'+(' checked' if n==5 else '')+' required><span aria-hidden="true">★</span><span class="sr">'+str(n)+' star'+('s' if n!=1 else '')+'</span></label>' for n in range(1,6))
    return '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Leave a review | Sports Cave</title><style>
*{box-sizing:border-box}body{margin:0;background:#fff;color:#222;font:15px system-ui,sans-serif}main{max-width:640px;margin:auto;padding:24px}h1{font-size:24px;line-height:1.25;margin:0 0 20px}h2{font-size:18px;margin:0 0 8px}p{line-height:1.5}header{display:flex;gap:16px;align-items:center;padding-bottom:20px;border-bottom:1px solid #ddd}.edition{object-fit:cover;border-radius:6px}fieldset{border:0;padding:18px 0;margin:0}legend{font-weight:600;padding-top:18px}.stars{display:flex;gap:6px}.stars label{position:relative;cursor:pointer}.stars input{position:absolute;opacity:0;width:100%;height:100%;margin:0}.stars span[aria-hidden]{font-size:36px;color:#b9b9b9}.stars label:has(input:checked) span[aria-hidden],.stars label:has(~label input:checked) span[aria-hidden]{color:#c69c36}.stars label:focus-within{outline:2px solid #222;outline-offset:3px}.setup{background:#f6f6f6;border:1px solid #ddd;border-radius:12px;padding:20px;margin-bottom:20px}.setup p{margin:8px 0}.upload{display:block;border:1px dashed #aaa;border-radius:8px;padding:16px;background:white;margin:16px 0 8px}label.field{display:block;font-weight:600;margin:16px 0}input[type=text],textarea{font:inherit;width:100%;padding:12px;border:1px solid #aaa;border-radius:6px;margin-top:8px}input[type=file]{max-width:100%;margin-top:10px;font:inherit;font-size:13px}button{font:inherit;font-weight:600;padding:13px 20px;background:#d4a54c;color:#171717;border:0;border-radius:8px;cursor:pointer}button:disabled{opacity:.6;cursor:wait}.consent{display:flex;align-items:flex-start;gap:8px;line-height:1.45;margin:20px 0}.consent input{margin-top:4px}.muted{font-size:13px;color:#555}.sr,.trap{position:absolute;width:1px;height:1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}[data-previews]{overflow-wrap:anywhere;display:flex;gap:8px;flex-wrap:wrap}[data-previews] img,[data-previews] video{width:88px;height:88px;object-fit:cover;border-radius:6px}[role=status]{line-height:1.5;outline:none}@media(max-width:420px){main{padding:16px}.setup{padding:16px}}[hidden]{display:none!important}
</style></head><body><main><h1>How does it look in your space?</h1><header>'''+hero+'<strong>'+title+'''</strong></header><form method="post" enctype="multipart/form-data"><input type="hidden" name="form_token" value="'''+escape(token or '',quote=True)+'''"><fieldset><legend>Your rating</legend><div class="stars">'''+rating+'''</div></fieldset><label class="field">Name<input name="reviewer_name" type="text" maxlength="120" required autocomplete="nickname"></label><label class="field">Review title (optional)<input name="title" type="text" maxlength="120"></label><label class="field">Your review<textarea name="body" minlength="10" maxlength="2000" rows="4" required placeholder="What stands out now that it’s on your wall?"></textarea></label><section class="setup"><h2>Show us your setup</h2><p>Start with the whole wall, then move in on your edition number.</p><label class="upload">Add photo/video (optional)<input type="file" name="media" accept="image/jpeg,image/png,image/webp,video/mp4,video/webm" multiple></label><div data-previews></div></section><label class="trap" aria-hidden="true">Website<input name="website" tabindex="-1" autocomplete="off"></label><input type="hidden" name="display_consent" value="yes"><p class="muted">By submitting, you agree to publish your review and attached media.</p><button type="submit">Submit review</button></form><p role="status" tabindex="-1" aria-live="polite"></p></main><script>'''+SCRIPT+'</script></body></html>'
